owers_url":"https://api.github.com/users/jahia-ci/followers","following_url":"https://api.github.com/users/jahia-ci/following{/other_user}","gists_url":"https://api.github.com/users/jahia-ci/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/jahia-ci","id":792788,"login":"jahia-ci","node_id":"MDQ6VXNlcjc5Mjc4OA==","organizations_url":"https://api.github.com/users/jahia-ci/orgs","received_events_url":"https://api.github.com/users/jahia-ci/received_events","repos_url":"https://api.github.com/users/jahia-ci/repos","site_admin":false,"starred_url":"https://api.github.com/users/jahia-ci/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/jahia-ci/subscriptions","type":"User","url":"https://api.github.com/users/jahia-ci","user_view_type":"public"},"comments_url":"https://api.github.com/repos/Jahia/jcontent/commits/81606f9e008bacb35adec79dec0357a082733a1d/comments","commit":{"author":{"date":"2026-08-14T13:33:13Z","email":"jahia-ci@jahia.com","name":"Jahia Continuous Integration account"},"comment_count":0,"committer":{"date":"2026-08-14T13:33:13Z","email":"jahia-ci@jahia.com","name":"Jahia Continuous Integration account"},"message":"[skip-ci] Cypress test module release v3.7.1-tests.1","tree":{"sha":"81b19d511f7a5dad0a2aac75028dee602a4e0012","url":"https://api.github.com/repos/Jahia/jcontent/git/trees/81b19d511f7a5dad0a2aac75028dee602a4e0012"},"url":"https://api.github.com/repos/Jahia/jcontent/git/commits/81606f9e008bacb35adec79dec0357a082733a1d","verification":{"payload":"tree 81b19d511f7a5dad0a2aac75028dee602a4e0012\nparent c6a41061a723e5471c73c502ead7609588a84a26\nauthor Jahia Continuous Integration account <jahia-ci@jahia.com> 1786714393 +0000\ncommitter Jahia Continuous Integration account <jahia-ci@jahia.com> 1786714393 +0000\n\n[skip-ci] Cypress test module release v3.7.1-tests.1\n","reason":"valid","signature":"-----BEGIN PGP SIGNATURE-----\n\niHUEABYKAB0WIQRleIRHMtIZVePIOmJodhkciXzSuQUCan8ZGQAKCRBodhkciXzS\nubCzAQDFv0KRzpp0hVQ7